<?php
 namespace Pterodactyl\Services\Dezerx\Staff; use Carbon\CarbonImmutable; use Illuminate\Database\ConnectionInterface; use Illuminate\Database\Eloquent\Builder; use Illuminate\Support\Str; use Pterodactyl\Exceptions\DisplayException; use Pterodactyl\Facades\Activity; use Pterodactyl\Jobs\RevokeSftpAccessJob; use Pterodactyl\Models\Dezerx\StaffProfile; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Models\Dezerx\StaffRequestEvent; use Pterodactyl\Models\Server; use Pterodactyl\Models\Subuser; use Pterodactyl\Models\User; use Pterodactyl\Services\Servers\GetUserPermissionsService; class StaffRequests { public const MAX_REASON = 2000; public const MAX_NOTE = 1000; public function __construct( private ConnectionInterface $connection, private GetUserPermissionsService $permissions, ) { } public function open(Server $server, User $actor, array $data): StaffRequest { $this->assertEnabled(); $direction = ($data['direction'] ?? StaffRequest::DIRECTION_OWNER) === StaffRequest::DIRECTION_STAFF ? StaffRequest::DIRECTION_STAFF : StaffRequest::DIRECTION_OWNER; $reason = $this->reason($data['reason'] ?? ''); $scope = StaffPresets::scope($data['scope'] ?? null); $duration = $this->duration($data); if ($direction === StaffRequest::DIRECTION_STAFF) { return $this->openAsStaff($server, $actor, $reason, $scope, $duration, $data); } return $this->openAsOwner($server, $actor, $reason, $scope, $duration, $data); } private function openAsOwner( Server $server, User $actor, string $reason, string $scope, ?int $duration, array $data ): StaffRequest { $target = null; $username = trim((string) ($data['username'] ?? '')); if ($username !== '') { if (!Staff::flag('allow_named')) { throw new DisplayException('Asking for a named staff member is switched off on this panel.'); } $target = $this->findStaffByUsername($username); $this->assertCanBeGranted($server, $target); if (!$this->available($target)) { throw new DisplayException('That staff member is not taking requests at the moment.'); } } elseif (!Staff::flag('allow_queue')) { throw new DisplayException('The support queue is switched off on this panel, name a staff member instead.'); } $permissions = StaffPresets::resolve($scope, $data['permissions'] ?? [], $this->permissions->handle($server, $actor)); return $this->connection->transaction(function () use ($server, $actor, $target, $reason, $scope, $duration, $permissions) { $this->assertSeatAvailable($server); $this->assertNotTooSoon($server); $request = $this->create([ 'server_id' => $server->id, 'requester_id' => $actor->id, 'target_staff_id' => $target?->id, 'staff_id' => null, 'direction' => StaffRequest::DIRECTION_OWNER, 'status' => StaffRequest::PENDING, 'reason' => $reason, 'scope' => $scope, 'permissions' => $permissions, 'requires_confirmation' => !Staff::autoAcceptFor($actor), 'duration_minutes' => $duration, ]); $this->record($request, $actor, StaffRequestEvent::OPENED); $this->logActivity('server:staff.open', $server, $actor, $request, [ 'named' => $target?->username, 'scope' => $scope, ]); StaffNotify::opened($request); return $request; }); } private function openAsStaff( Server $server, User $actor, string $reason, string $scope, ?int $duration, array $data ): StaffRequest { if (!Staff::flag('allow_staff_requests')) { throw new DisplayException('Staff cannot ask for access on this panel.'); } if (!Staff::canAct($actor)) { throw new DisplayException('Only support staff can ask for access to somebody else\'s server.'); } $this->assertCanBeGranted($server, $actor); $this->assertClaimAllowed($actor); $owner = $server->user; $permissions = StaffPresets::resolve($scope, $data['permissions'] ?? [], $this->permissions->handle($server, $owner)); return $this->connection->transaction(function () use ($server, $actor, $owner, $reason, $scope, $duration, $permissions) { $this->assertSeatAvailable($server); $request = $this->create([ 'server_id' => $server->id, 'requester_id' => $actor->id, 'target_staff_id' => null, 'staff_id' => $actor->id, 'direction' => StaffRequest::DIRECTION_STAFF, 'status' => StaffRequest::PENDING, 'reason' => $reason, 'scope' => $scope, 'permissions' => $permissions, 'requires_confirmation' => !Staff::autoAcceptFor($owner), 'duration_minutes' => $duration, 'claimed_at' => now(), ]); $this->record($request, $actor, StaffRequestEvent::OPENED); $this->logActivity('server:staff.ask', $server, $actor, $request, ['scope' => $scope]); if (!$request->requires_confirmation) { $this->grant($request, $actor, $actor); return $request; } StaffNotify::asked($request); return $request; }); } public function claim(StaffRequest $request, User $staff): StaffRequest { $this->assertEnabled(); if (!Staff::canAct($staff)) { throw new DisplayException('Only support staff can take on a request.'); } $this->assertClaimAllowed($staff); return $this->connection->transaction(function () use ($request, $staff) { $request = $this->lock($request); if (!$request->isPending()) { throw new DisplayException('That request is no longer waiting for anybody.'); } if ($request->direction === StaffRequest::DIRECTION_STAFF) { throw new DisplayException('That request is waiting on the server owner, not on staff.'); } if ($request->target_staff_id !== null && $request->target_staff_id !== $staff->id) { throw new DisplayException('That request was addressed to somebody else.'); } $server = $request->server; $this->assertCanBeGranted($server, $staff); $request->forceFill(['staff_id' => $staff->id, 'claimed_at' => now()])->saveOrFail(); $this->record($request, $staff, StaffRequestEvent::CLAIMED); $this->logActivity('server:staff.claim', $server, $staff, $request); $this->touchProfile($staff); if ($request->requires_confirmation) { $request->forceFill(['status' => StaffRequest::CLAIMED])->saveOrFail(); StaffNotify::claimed($request); return $request; } $this->grant($request, $staff, $staff); return $request; }); } public function confirm(StaffRequest $request, User $actor): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $actor) { $request = $this->lock($request); if (!$request->isClaimed()) { throw new DisplayException('There is nobody waiting to be let in on that request.'); } $staff = $request->staff; if ($staff === null) { throw new DisplayException('The staff member who took that on is no longer available.'); } $this->assertCanBeGranted($request->server, $staff); $this->record($request, $actor, StaffRequestEvent::CONFIRMED); $this->grant($request, $staff, $actor); return $request; }); } public function approve(StaffRequest $request, User $actor): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $actor) { $request = $this->lock($request); if (!$request->isPending() || $request->direction !== StaffRequest::DIRECTION_STAFF) { throw new DisplayException('That request is not waiting for your approval.'); } $staff = $request->staff; if ($staff === null || !Staff::canAct($staff)) { throw new DisplayException('The staff member who asked is no longer available.'); } $this->assertCanBeGranted($request->server, $staff); $this->record($request, $actor, StaffRequestEvent::CONFIRMED); $this->grant($request, $staff, $actor); return $request; }); } public function decline(StaffRequest $request, User $staff, string $reason): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $staff, $reason) { $request = $this->lock($request); if (!$request->isPending() && !$request->isClaimed()) { throw new DisplayException('That request has already been settled.'); } $this->close($request, StaffRequest::DECLINED, $staff, StaffRequestEvent::DECLINED, [ 'decline_reason' => $this->note($reason), 'staff_id' => $staff->id, ]); $this->logActivity('server:staff.decline', $request->server, $staff, $request); $this->touchProfile($staff); StaffNotify::declined($request); return $request; }); } public function deny(StaffRequest $request, User $actor, string $reason): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $actor, $reason) { $request = $this->lock($request); if (!$request->isPending() && !$request->isClaimed()) { throw new DisplayException('That request has already been settled.'); } $this->close($request, StaffRequest::DECLINED, $actor, StaffRequestEvent::DENIED, [ 'decline_reason' => $this->note($reason), ]); $this->logActivity('server:staff.deny', $request->server, $actor, $request); StaffNotify::denied($request); return $request; }); } public function cancel(StaffRequest $request, User $actor): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $actor) { $request = $this->lock($request); if (!$request->isPending() && !$request->isClaimed()) { throw new DisplayException('That request cannot be called off now.'); } $this->close($request, StaffRequest::CANCELLED, $actor, StaffRequestEvent::CANCELLED); $this->logActivity('server:staff.cancel', $request->server, $actor, $request); StaffNotify::cancelled($request); return $request; }); } public function withdraw(StaffRequest $request, User $staff): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $staff) { $request = $this->lock($request); if (!$request->isClaimed() || $request->staff_id !== $staff->id) { throw new DisplayException('You have not taken that request on.'); } $request->forceFill([ 'status' => StaffRequest::PENDING, 'staff_id' => null, 'claimed_at' => null, ])->saveOrFail(); $this->record($request, $staff, StaffRequestEvent::WITHDRAWN); $this->logActivity('server:staff.withdraw', $request->server, $staff, $request); StaffNotify::withdrawn($request, $staff); return $request; }); } public function resign(StaffRequest $request, User $staff, string $note = ''): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $staff, $note) { $request = $this->lock($request); if (!$request->isActive() || $request->staff_id !== $staff->id) { throw new DisplayException('You are not working on that server.'); } $remaining = $request->isOpenEnded() ? null : max(Staff::MIN_DURATION, (int) $request->minutesLeft()); $this->revokeAccess($request); $request->forceFill([ 'status' => StaffRequest::PENDING, 'staff_id' => null, 'target_staff_id' => null, 'claimed_at' => null, 'approved_at' => null, 'started_at' => null, 'expires_at' => null, 'reminded_at' => null, 'extension_minutes' => null, 'extension_note' => null, 'remaining_minutes' => $remaining, 'handoffs' => $request->handoffs + 1, ])->saveOrFail(); $this->record($request, $staff, StaffRequestEvent::RESIGNED, $this->note($note)); $this->logActivity('server:staff.resign', $request->server, $staff, $request); $this->touchProfile($staff); StaffNotify::resigned($request, $staff, $this->note($note)); return $request; }); } public function resolve(StaffRequest $request, User $staff, string $note = ''): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $staff, $note) { $request = $this->lock($request); if (!$request->isActive() || ($request->staff_id !== $staff->id && !$staff->root_admin)) { throw new DisplayException('That session is not yours to finish.'); } $this->revokeAccess($request); $this->close($request, StaffRequest::RESOLVED, $staff, StaffRequestEvent::RESOLVED, [ 'resolution' => $this->note($note), ]); $this->logActivity('server:staff.resolve', $request->server, $staff, $request); $this->touchProfile($staff); StaffNotify::resolved($request); return $request; }); } public function revoke(StaffRequest $request, ?User $actor, string $reason = ''): StaffRequest { return $this->connection->transaction(function () use ($request, $actor, $reason) { $request = $this->lock($request); if (!$request->isOpen()) { throw new DisplayException('That session has already ended.'); } $this->revokeAccess($request); $this->close($request, StaffRequest::REVOKED, $actor, StaffRequestEvent::REVOKED, [ 'resolution' => $this->note($reason), ]); $this->logActivity('server:staff.revoke', $request->server, $actor, $request); StaffNotify::revoked($request); return $request; }); } public function expire(StaffRequest $request): StaffRequest { return $this->connection->transaction(function () use ($request) { $request = $this->lock($request); if (!$request->isOpen()) { return $request; } $this->revokeAccess($request); $this->close($request, StaffRequest::EXPIRED, null, StaffRequestEvent::EXPIRED); $this->logActivity('server:staff.expire', $request->server, null, $request); StaffNotify::expired($request); return $request; }); } public function askExtension(StaffRequest $request, User $staff, int $minutes, string $note = ''): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $staff, $minutes, $note) { $request = $this->lock($request); if (!$request->isActive() || $request->staff_id !== $staff->id) { throw new DisplayException('You are not working on that server.'); } if ($request->isOpenEnded()) { throw new DisplayException('That session has no time limit to extend.'); } $this->assertExtensionsLeft($request); $request->forceFill([ 'extension_minutes' => $this->extensionMinutes($minutes), 'extension_note' => $this->note($note), ])->saveOrFail(); $this->record($request, $staff, StaffRequestEvent::EXTENSION_ASKED, $this->note($note)); StaffNotify::extensionAsked($request); return $request; }); } public function grantExtension(StaffRequest $request, User $actor, ?int $minutes = null): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $actor, $minutes) { $request = $this->lock($request); if (!$request->isActive()) { throw new DisplayException('That session is not running.'); } if ($request->isOpenEnded()) { throw new DisplayException('That session has no time limit to extend.'); } $this->assertExtensionsLeft($request); $asked = $minutes ?? $request->extension_minutes; if ($asked === null) { throw new DisplayException('Say how much longer the session should run for.'); } $added = $this->extensionMinutes((int) $asked); $from = $request->expires_at !== null && $request->expires_at->isFuture() ? CarbonImmutable::instance($request->expires_at) : CarbonImmutable::now(); $request->forceFill([ 'expires_at' => $from->addMinutes($added), 'duration_minutes' => min(Staff::CEILING_DURATION, (int) $request->duration_minutes + $added), 'extensions' => $request->extensions + 1, 'extension_minutes' => null, 'extension_note' => null, 'reminded_at' => null, ])->saveOrFail(); $this->record($request, $actor, StaffRequestEvent::EXTENSION_GRANTED, $added . ' minutes'); $this->logActivity('server:staff.extend', $request->server, $actor, $request, ['minutes' => $added]); StaffNotify::extended($request, $added); return $request; }); } public function denyExtension(StaffRequest $request, User $actor): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $actor) { $request = $this->lock($request); if ($request->extension_minutes === null) { throw new DisplayException('Nobody has asked for more time on that session.'); } $request->forceFill(['extension_minutes' => null, 'extension_note' => null])->saveOrFail(); $this->record($request, $actor, StaffRequestEvent::EXTENSION_DENIED); StaffNotify::extensionDenied($request); return $request; }); } public function trim(StaffRequest $request, User $actor, array $permissions): StaffRequest { $this->assertEnabled(); return $this->connection->transaction(function () use ($request, $actor, $permissions) { $request = $this->lock($request); if (!$request->isOpen()) { throw new DisplayException('That session has already ended.'); } $granter = $request->server->user; $cleaned = StaffPresets::resolve( $request->scope, $permissions, $this->permissions->handle($request->server, $granter) ); $request->forceFill(['permissions' => $cleaned])->saveOrFail(); $subuser = $request->subuser; if ($subuser !== null) { $subuser->forceFill(['permissions' => $cleaned])->saveOrFail(); RevokeSftpAccessJob::dispatch($subuser->user->uuid, $request->server); } $this->record($request, $actor, StaffRequestEvent::TRIMMED); $this->logActivity('server:staff.trim', $request->server, $actor, $request, ['permissions' => $cleaned]); return $request; }); } public function endEverything(?User $actor): int { $count = 0; foreach (StaffRequest::query()->open()->cursor() as $request) { $this->revoke($request, $actor, 'The support staff system was switched off.'); ++$count; } return $count; } public function queueFor(User $staff): Builder { $query = StaffRequest::query() ->with(['server.egg', 'server.user', 'staff', 'target', 'requester', 'feedback']) ->where('status', StaffRequest::PENDING) ->where('direction', StaffRequest::DIRECTION_OWNER); if (!$staff->root_admin) { $query->where(function (Builder $builder) use ($staff) { $builder->whereNull('target_staff_id')->orWhere('target_staff_id', $staff->id); }); } return $query->latest('id'); } public function mineFor(User $staff): Builder { return StaffRequest::query() ->with(['server.egg', 'server.user', 'staff', 'target', 'requester', 'feedback']) ->where('staff_id', $staff->id) ->whereIn('status', StaffRequest::OPEN_STATUSES) ->latest('id'); } public function historyFor(User $staff): Builder { return StaffRequest::query() ->with(['server.egg', 'server.user', 'staff', 'target', 'requester', 'feedback']) ->where('staff_id', $staff->id) ->whereIn('status', StaffRequest::CLOSED_STATUSES) ->latest('id'); } public function pendingOwnerActionFor(User $owner): Builder { return StaffRequest::query() ->whereIn('status', [StaffRequest::PENDING, StaffRequest::CLAIMED]) ->whereHas('server', fn (Builder $builder) => $builder->where('owner_id', $owner->id)) ->latest('id'); } public function forServer(Server $server): Builder { return StaffRequest::query() ->with(['server.egg', 'server.user', 'staff', 'target', 'requester', 'feedback']) ->where('server_id', $server->id) ->latest('id'); } private function create(array $attributes): StaffRequest { $request = new StaffRequest($attributes); $request->uuid = Str::uuid()->toString(); $request->saveOrFail(); return $request; } private function grant(StaffRequest $request, User $staff, ?User $actor): void { $server = $request->server; $granter = $server->user; $permissions = StaffPresets::resolve( $request->scope, $request->permissions ?? [], $this->permissions->handle($server, $granter) ); $minutes = $request->remaining_minutes ?? $request->duration_minutes; $expires = $minutes === null ? null : CarbonImmutable::now()->addMinutes(Staff::clampDuration((int) $minutes)); $subuser = new Subuser([ 'user_id' => $staff->id, 'server_id' => $server->id, 'permissions' => $permissions, ]); $subuser->dezerx_staff_request_id = $request->id; $subuser->saveOrFail(); $request->forceFill([ 'status' => StaffRequest::ACTIVE, 'staff_id' => $staff->id, 'permissions' => $permissions, 'approved_at' => now(), 'started_at' => now(), 'expires_at' => $expires, 'remaining_minutes' => null, 'reminded_at' => null, ])->saveOrFail(); $this->record($request, $staff, StaffRequestEvent::GRANTED); $this->logActivity('server:staff.grant', $server, $actor, $request, [ 'staff' => $staff->username, 'permissions' => $permissions, ]); $this->touchProfile($staff); StaffNotify::granted($request); } private function revokeAccess(StaffRequest $request): void { $rows = Subuser::query()->where('dezerx_staff_request_id', $request->id)->get(); foreach ($rows as $subuser) { $uuid = $subuser->user->uuid; $subuser->delete(); RevokeSftpAccessJob::dispatch($uuid, $request->server); } StaffAccess::forget(); } private function close( StaffRequest $request, string $status, ?User $actor, string $action, array $extra = [] ): void { $request->forceFill([ ...$extra, 'status' => $status, 'ended_at' => now(), 'expires_at' => null, 'extension_minutes' => null, 'extension_note' => null, 'remaining_minutes' => null, ])->saveOrFail(); $this->record($request, $actor, $action, $extra['decline_reason'] ?? $extra['resolution'] ?? null); } private function record(StaffRequest $request, ?User $actor, string $action, ?string $note = null): void { StaffRequestEvent::query()->create([ 'request_id' => $request->id, 'actor_id' => $actor?->id, 'action' => $action, 'note' => $note === '' ? null : $note, 'created_at' => now(), ]); } private function logActivity( string $event, ?Server $server, ?User $actor, StaffRequest $request, array $properties = [] ): void { $log = Activity::event($event)->property([...$properties, 'request' => $request->uuid]); if ($server !== null) { $log = $log->subject($server); } if ($actor !== null) { $log = $log->actor($actor); } else { $log = $log->anonymous(); } $log->log(); } private function lock(StaffRequest $request): StaffRequest { $locked = StaffRequest::query()->whereKey($request->id)->lockForUpdate()->first(); if ($locked === null) { throw new DisplayException('That request no longer exists.'); } return $locked; } private function assertEnabled(): void { if (!Staff::enabled()) { throw new DisplayException('The support staff system is switched off on this panel.'); } } private function assertSeatAvailable(Server $server): void { if (Staff::seatsLeft($server->id) <= 0) { throw new DisplayException('This server has as many staff requests open as it is allowed.'); } } private function assertNotTooSoon(Server $server): void { $cooldown = Staff::number('cooldown_minutes'); if ($cooldown <= 0) { return; } $recent = StaffRequest::query() ->where('server_id', $server->id) ->where('created_at', '>=', now()->subMinutes($cooldown)) ->exists(); if ($recent) { throw new DisplayException('A request was opened for this server a moment ago, give it a minute.'); } } private function assertClaimAllowed(User $staff): void { if (Staff::flag('require_2fa') && $staff->use_totp !== true) { throw new DisplayException('Turn on two factor authentication before taking on support work.'); } $profile = $staff->staffProfile; if ($profile instanceof StaffProfile && !$profile->available && !$staff->root_admin) { throw new DisplayException('You are marked as unavailable, turn yourself back on first.'); } $cap = Staff::number('max_active_per_staff'); if ($profile instanceof StaffProfile && $profile->max_active > 0) { $cap = min($cap, $profile->max_active); } if ($cap <= 0) { return; } $active = StaffRequest::query() ->where('staff_id', $staff->id) ->whereIn('status', [StaffRequest::CLAIMED, StaffRequest::ACTIVE]) ->count(); if ($active >= $cap) { throw new DisplayException('You are already on as many servers as you are allowed at once.'); } } private function assertExtensionsLeft(StaffRequest $request): void { $max = Staff::number('max_extensions'); if ($max > 0 && $request->extensions >= $max) { throw new DisplayException('That session has had all the extensions it is allowed.'); } } private function assertCanBeGranted(Server $server, User $staff): void { if ($server->owner_id === $staff->id) { throw new DisplayException('That account already owns this server.'); } $existing = Subuser::query() ->where('server_id', $server->id) ->where('user_id', $staff->id) ->first(); if ($existing !== null && $existing->dezerx_staff_request_id === null) { throw new DisplayException('That account already has its own access to this server.'); } if ($existing !== null) { throw new DisplayException('That account is already working on this server.'); } } private function findStaffByUsername(string $username): User { $user = User::query()->whereRaw('LOWER(username) = ?', [mb_strtolower($username)])->first(); if ($user === null || $user->staff !== true) { throw new DisplayException('No support staff account goes by that username.'); } return $user; } private function available(User $staff): bool { $profile = $staff->staffProfile; return !($profile instanceof StaffProfile) || $profile->available; } private function touchProfile(User $staff): void { $profile = $staff->staffProfile; if ($profile instanceof StaffProfile) { $profile->forceFill(['last_active_at' => now()])->saveOrFail(); } } private function reason(string $value): string { $reason = trim($value); $minimum = Staff::number('reason_min_length'); if (mb_strlen($reason) < $minimum) { throw new DisplayException('Say a little more about what you need help with, at least ' . $minimum . ' characters.'); } return mb_substr($reason, 0, self::MAX_REASON); } private function note(string $value): string { return mb_substr(trim($value), 0, self::MAX_NOTE); } private function duration(array $data): ?int { $open = ($data['open_ended'] ?? false) === true; if ($open) { if (!Staff::openEndedAllowed()) { throw new DisplayException('Sessions without a time limit are switched off on this panel.'); } return null; } $minutes = $data['duration_minutes'] ?? null; if ($minutes === null || (int) $minutes <= 0) { return Staff::defaultDuration(); } return Staff::clampDuration((int) $minutes); } private function extensionMinutes(int $minutes): int { $max = Staff::number('extension_max_minutes'); return max(Staff::MIN_DURATION, min($minutes, $max > 0 ? $max : Staff::maxDuration())); } } 